package pool

import (
	"reflect"
	"sync/atomic"
	"testing"
)

func TestOrder(t *testing.T) {
	jobs := make([]int, 100)
	for i := range jobs {
		jobs[i] = i
	}
	got := ProcessAll(jobs, 8, func(x int) int { return x * 2 })
	want := make([]int, 100)
	for i := range want {
		want[i] = i * 2
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("order broken: %v", got[:10])
	}
}

func TestParallel(t *testing.T) {
	var cnt int64
	ProcessAll([]int{1, 2, 3, 4}, 0, func(x int) int {
		atomic.AddInt64(&cnt, 1)
		return x
	})
	if cnt != 4 {
		t.Fatalf("fn not applied to all: %d", cnt)
	}
}

func TestEmpty(t *testing.T) {
	got := ProcessAll(nil, 4, func(x int) int { return x })
	if len(got) != 0 {
		t.Fatalf("want empty")
	}
}

