const assert = require('assert');
const { Emitter } = require('./solution.js');

const e = new Emitter();
const seen = [];
const h1 = (x) => seen.push('h1:' + x);
e.on('a', h1).on('a', (x) => seen.push('h2:' + x));
assert.strictEqual(e.emit('a', 1), 2);
assert.deepStrictEqual(seen, ['h1:1', 'h2:1']);

e.off('a', h1);
seen.length = 0;
e.emit('a', 2);
assert.deepStrictEqual(seen, ['h2:2']);

// once + reentrant emit
const e2 = new Emitter();
let count = 0;
e2.once('t', () => { count++; e2.emit('t'); });
e2.emit('t');
assert.strictEqual(count, 1);

// off during emit (snapshot semantics)
const e3 = new Emitter();
const out = [];
const a = () => { out.push('a'); e3.off('x', b); };
const b = () => out.push('b');
e3.on('x', a); e3.on('x', b);
e3.emit('x');
assert.deepStrictEqual(out, ['a', 'b']);
e3.emit('x');
assert.deepStrictEqual(out, ['a', 'b', 'a']);
console.log('OK');

