const assert = require("assert");
const { page } = require("./solution.js");

const enc = (ts, id) => Buffer.from(`${ts}:${id}`).toString("base64url");
const mk = (ts, id) => ({ ts, id, actor: `u-${id}` });
const events = [
  mk(300, "a1"), mk(250, "b2"),
  mk(200, "c1"), mk(200, "c2"), mk(200, "c3"),
  mk(150, "d1"),
  mk(100, "e1"), mk(100, "e2"),
  mk(50, "f9"),
];
const snapshot = events.map(e => ({ ...e }));
const ids = r => r.items.map(e => e.id);

let r = page(events, null, 2);
assert.deepStrictEqual(ids(r), ["a1", "b2"], "head page");
assert.strictEqual(r.nextCursor, enc(250, "b2"), "head page nextCursor token");

r = page(events, r.nextCursor, 2);
assert.deepStrictEqual(ids(r), ["c1", "c2"], "must stop mid tie group");
assert.strictEqual(r.nextCursor, enc(200, "c2"));
assert.strictEqual(Buffer.from(r.nextCursor, "base64url").toString(), "200:c2", "token round-trip");

r = page(events, enc(200, "c2"), 2);
assert.deepStrictEqual(ids(r), ["c3", "d1"], "resume inside tie group");
assert.strictEqual(r.nextCursor, enc(150, "d1"));

r = page(events, enc(150, "d1"), 3);
assert.deepStrictEqual(ids(r), ["e1", "e2", "f9"], "exact-fit last page");
assert.strictEqual(r.nextCursor, null, "exact-fit last page has no next cursor");

r = page(events, enc(220, "zzz"), 3);
assert.deepStrictEqual(ids(r), ["c1", "c2", "c3"], "compacted key between two events");

r = page(events, enc(200, "c1x"), 2);
assert.deepStrictEqual(ids(r), ["c2", "c3"], "compacted key inside a tie group");

r = page(events, enc(999, "aaa"), 3);
assert.deepStrictEqual(ids(r), ["a1", "b2", "c1"], "key newer than every event");

r = page(events, enc(1, "z"), 3);
assert.deepStrictEqual(r.items, [], "key older than every event");
assert.strictEqual(r.nextCursor, null);

r = page(events, null, 20);
assert.strictEqual(r.items.length, 9);
assert.strictEqual(r.nextCursor, null);

let cur = null, seen = [], iters = 0;
do {
  const p = page(events, cur, 3);
  seen = seen.concat(p.items);
  cur = p.nextCursor;
  iters++;
  assert.ok(iters <= 10, "driver loop did not terminate");
} while (cur !== null);
assert.strictEqual(iters, 3, "full walk takes 3 pages");
assert.deepStrictEqual(seen, events, "full walk must reproduce the log exactly once");

assert.throws(() => page(events, "not-base64!!", 2), TypeError);
assert.throws(() => page(events, Buffer.from("nocolon").toString("base64url"), 2), TypeError);
assert.throws(() => page(events, Buffer.from("abc:ID").toString("base64url"), 2), TypeError);
assert.throws(() => page(events, 42, 2), TypeError);

assert.throws(() => page(events, null, 0), RangeError);
assert.throws(() => page(events, null, -1), RangeError);
assert.throws(() => page(events, null, 2.5), RangeError);

assert.deepStrictEqual(events, snapshot, "input must not be mutated or re-sorted");
console.log("ok");

