import random
import unittest
from solution import to_roman

OV = "\u0305"
DOV = "\u033f"
MACRON = "\u0304"
VALS = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"),
        (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"),
        (5, "V"), (4, "IV"), (1, "I")]


def plain_encode(n):
    out = []
    for v, sym in VALS:
        while n >= v:
            out.append(sym)
            n -= v
    return "".join(out)


def mark(s, m):
    return "".join(c + m for c in s)


def ref(n):
    if n < 4000:
        return plain_encode(n)
    m = n // 1000000
    t = (n // 1000) % 1000
    r = n % 1000
    out = ""
    if m:
        out += mark(plain_encode(m), DOV)
    if t:
        out += mark(plain_encode(t), OV)
    if r:
        out += plain_encode(r)
    return out


def parse_plain(s):
    i = 0
    total = 0
    while i < len(s):
        for v, sym in VALS:
            if s.startswith(sym, i):
                total += v
                i += len(sym)
                break
        else:
            raise AssertionError("not a valid roman segment: %r" % s)
    if plain_encode(total) != s:
        raise AssertionError("segment not canonical: %r" % s)
    return total


def split_groups(s):
    groups = {2: [], 1: [], 0: []}
    order = []
    i = 0
    while i < len(s):
        ch = s[i]
        if ch not in "IVXLCDM":
            raise AssertionError("unexpected character %r in %r" % (ch, s))
        i += 1
        lvl = 0
        if i < len(s) and s[i] in (OV, DOV):
            lvl = 2 if s[i] == DOV else 1
            i += 1
            if i < len(s) and s[i] in (OV, DOV):
                raise AssertionError("two marks on one letter in %r" % s)
        groups[lvl].append(ch)
        if not order or order[-1] != lvl:
            order.append(lvl)
    if order != sorted(set(order), reverse=True):
        raise AssertionError("groups out of order in %r" % s)
    return "".join(groups[2]), "".join(groups[1]), "".join(groups[0])


class T(unittest.TestCase):
    def test_unbarred_regime(self):
        self.assertEqual(to_roman(1), "I")
        self.assertEqual(to_roman(4), "IV")
        self.assertEqual(to_roman(9), "IX")
        self.assertEqual(to_roman(58), "LVIII")
        self.assertEqual(to_roman(1994), "MCMXCIV")
        self.assertEqual(to_roman(1000), "M")
        self.assertEqual(to_roman(3999), "MMMCMXCIX")
        for n in (1, 4, 9, 58, 1994, 1000, 3999):
            s = to_roman(n)
            self.assertNotIn(OV, s)
            self.assertNotIn(DOV, s)

    def test_boundary_4000(self):
        self.assertEqual(to_roman(4000), "I\u0305V\u0305")
        self.assertEqual(to_roman(4001), "I\u0305V\u0305I")
        self.assertEqual(to_roman(4999), "I\u0305V\u0305CMXCIX")

    def test_million_boundary(self):
        self.assertEqual(
            to_roman(999999),
            "C\u0305M\u0305X\u0305C\u0305I\u0305X\u0305CMXCIX",
        )
        self.assertEqual(to_roman(1000000), "I\u033f")
        self.assertEqual(to_roman(1000001), "I\u033fI")
        self.assertEqual(to_roman(1001000), "I\u033fI\u0305")

    def test_worked_examples(self):
        self.assertEqual(
            to_roman(3999999),
            "I\u033fI\u033fI\u033fC\u0305M\u0305X\u0305C\u0305I\u0305X\u0305CMXCIX",
        )
        self.assertEqual(to_roman(4000000), "I\u033fV\u033f")
        self.assertEqual(to_roman(2000000005), "M\u033fM\u033fV")
        self.assertEqual(to_roman(1000000000), "M\u033f")

    def test_maximum(self):
        self.assertEqual(
            to_roman(3999999999),
            "M\u033fM\u033fM\u033fC\u033fM\u033fX\u033fC\u033fI\u033fX\u033f"
            "C\u0305M\u0305X\u0305C\u0305I\u0305X\u0305CMXCIX",
        )

    def test_interior_zero_group(self):
        rng = random.Random(1234)
        cases = [1000000, 1000001, 2000000005, 3000000007, 1000000999]
        cases += [rng.randint(1, 3999) * 1000000 + rng.randint(0, 999)
                  for _ in range(120)]
        for n in cases:
            s = to_roman(n)
            self.assertNotIn(OV, s, "stray single overline for %d: %r" % (n, s))
            self.assertEqual(s, ref(n), "mismatch for %d" % n)

    def test_millions_sweep(self):
        for m in range(1, 4000):
            n = m * 1000000
            s = to_roman(n)
            self.assertEqual(s, mark(plain_encode(m), DOV), "wrong for m=%d" % m)
            self.assertNotIn(OV, s)

    def test_structure_random(self):
        rng = random.Random(20240517)
        sample = [4000, 4321, 12345, 99999, 500000, 2500001, 1000000,
                  1999999, 999999999, 3999999999]
        sample += [rng.randint(4000, 3999999999) for _ in range(500)]
        for n in sample:
            s = to_roman(n)
            self.assertTrue(set(s) <= set("IVXLCDM" + OV + DOV),
                            "bad charset for %d: %r" % (n, s))
            self.assertNotIn(MACRON, s)
            self.assertNotIn("MMMM", s)
            g2, g1, g0 = split_groups(s)
            self.assertEqual(parse_plain(g2) if g2 else 0, n // 1000000,
                             "millions group wrong for %d" % n)
            self.assertEqual(parse_plain(g1) if g1 else 0, (n // 1000) % 1000,
                             "thousands group wrong for %d" % n)
            self.assertEqual(parse_plain(g0) if g0 else 0, n % 1000,
                             "units group wrong for %d" % n)
            self.assertLess(parse_plain(g1) if g1 else 0, 1000)
            self.assertLess(parse_plain(g0) if g0 else 0, 1000)
            self.assertEqual(s, ref(n), "mismatch for %d" % n)

    def test_roundtrip_all_small(self):
        for n in range(1, 4000):
            s = to_roman(n)
            self.assertNotIn(OV, s)
            self.assertNotIn(DOV, s)
            self.assertEqual(parse_plain(s), n)
            self.assertEqual(s, ref(n))

    def test_legacy_range_extension(self):
        rng = random.Random(99)
        for n in [4000, 4999, 123456, 999999] + [rng.randint(4000, 999999) for _ in range(200)]:
            s = to_roman(n)
            self.assertNotIn(DOV, s, "unexpected double overline for %d: %r" % (n, s))
            expected = mark(plain_encode(n // 1000), OV) + plain_encode(n % 1000)
            self.assertEqual(s, expected, "mismatch for %d" % n)

    def test_matches_reference(self):
        rng = random.Random(7)
        pool = [4000, 4999, 1000000, 3999999, 4000000, 1000000000, 3999999999]
        pool += [rng.randint(1, 3999999999) for _ in range(400)]
        for n in pool:
            self.assertEqual(to_roman(n), ref(n), "mismatch for %d" % n)

    def test_errors(self):
        for bad in (0, -1, -1000, 4000000000, 10 ** 12):
            with self.assertRaises(ValueError):
                to_roman(bad)

    def test_no_error_inside_range(self):
        self.assertIsInstance(to_roman(1), str)
