import inspect
import unittest
from solution import first_free


def brute(busy, duration, day_start=540, day_end=1080, granularity=15):
    blocks = []
    for a, b in busy:
        a2 = max(a, day_start)
        b2 = min(b, day_end)
        if a2 < b2:
            blocks.append((a2, b2))
    s = day_start
    while s + duration <= day_end:
        ok = True
        for a, b in blocks:
            if s < b and a < s + duration:
                ok = False
                break
        if ok:
            return s
        s += granularity
    return None


class T(unittest.TestCase):
