    def test_matches_bruteforce_and_is_valid(self):
        cases = [
            ([], 30, 540, 1080, 15),
            ([(540, 601)], 30, 540, 1080, 15),
            ([(540, 606), (636, 1080)], 30, 540, 1080, 15),
            ([(540, 606), (636, 700), (800, 1080)], 30, 540, 1080, 15),
            ([(0, 540), (660, 720), (540, 600), (570, 690), (1050, 2000), (600, 600)], 30, 540, 1080, 15),
            ([(600, 630), (700, 760)], 45, 540, 1080, 20),
            ([(540, 1051)], 30, 540, 1080, 15),
            ([(545, 560), (561, 570)], 7, 540, 600, 7),
            ([(540, 600)], 90, 540, 1080, 45),
            ([(700, 705), (705, 710), (709, 900)], 13, 540, 1080, 11),
        ]
        for busy, dur, ds, de, g in cases:
            got = first_free(busy, dur, ds, de, g)
            want = brute(busy, dur, ds, de, g)
            self.assertEqual(got, want, msg=repr((busy, dur, ds, de, g)))
            if got is not None:
                self.assertEqual((got - ds) % g, 0)
                self.assertGreaterEqual(got, ds)
                self.assertLessEqual(got + dur, de)
                for a, b in busy:
                    a2, b2 = max(a, ds), min(b, de)
                    if a2 < b2:
                        self.assertFalse(got < b2 and a2 < got + dur)
